INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('24198974-96e5-4c69-8c2e-cc6246ded16e', 'dc7af11c-6130-46f6-b80a-c9eb5c289b3e', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('2a1ea873-7b1a-43b9-85a4-633371558d08', 'dc7af11c-6130-46f6-b80a-c9eb5c289b3e', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('87000da4-a80f-465d-a9a6-52dfab6735f3', 'dc7af11c-6130-46f6-b80a-c9eb5c289b3e', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('218ad204-d536-4dc2-ac69-b8efa49ce63f', 'ACP-Q-0447', 1, 'published', 'p-mpharm', 'sub-depression', 'medium', 'sba', 'hospital', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('e7a12044-f963-4956-813c-e900a10a2fb9', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'A 26-year-old female with generalised epilepsy attends community pharmacy for a repeat prescription of Sodium Valproate 500 mg tablets. She mentions she stopped using contraception two months ago. (Case Ref: CNS-0447). Relevant physiological and medication history have been reviewed.', 'What is the essential action for the pharmacist to take before dispensing this medication?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1071fd17-dcc6-44ea-9ec2-8e70200feb0e', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'A', 'Confirm active enrollment in the Valproate Pregnancy Prevention Programme (prevent) with signed Annual Risk Acknowledgement and immediate referral to prescriber', 1, 'Correct. Valproate is strictly contraindicated in women of childbearing potential unless conditions of the Pregnancy Prevention Programme are met due to 10% teratogenicity and 30-40% neurodevelopmental disorders.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('04fdb921-0041-45aa-b927-1441c12a2403', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'B', 'Dispense the full 3-month supply and advise patient to buy over-the-counter pregnancy test', 0, 'Sub-optimal and regulatory failure. Pharmacists must verify Annual Risk Acknowledgement form before dispensing.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('01824858-0001-4c20-a137-a8ade5f2b735', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e41c6761-fd17-4931-a8a7-cdb8a97081d8', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('870c97df-4f9d-408e-9b61-a4a07bb222b7', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'E', 'Supply in plain white dispensing bottle with original warning triangle discarded', 0, 'Illegal practice. Valproate must always be dispensed in original manufacturer packaging with visible pregnancy warning icon.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f546efb8-d210-4503-8001-60c8988516aa', '218ad204-d536-4dc2-ac69-b8efa49ce63f', 'Valproate must only be dispensed in original packaging to female patients with verified Pregnancy Prevention Programme compliance.', 'Teratogenic risks include neural tube defects, facial clefts, and severe autism spectrum disorders. Reference: MHRA Drug Safety Update: Valproate safety measures.', 'MHRA Drug Safety Update: Valproate safety measures', 1789735204, 1789735204);
