INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1fb43942-7c03-4ac7-8fa3-65e480928e9d', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'A 68-year-old non-pregnant female with lower urinary tract infection symptoms (dysuria, frequency, no fever or flank pain) has a documented eGFR of 32 mL/min. (Case Ref: INFECTIONS-0498). Relevant physiological and medication history have been reviewed.', 'Which empirical oral antimicrobial is most appropriate under UKHSA guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9aa9a90a-7aaa-4195-8a63-337e8e270769', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8c2c7267-b582-4842-903f-9d2f4b301c89', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e4bb56f7-6912-443f-807c-8db5e8b49dfd', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6751e316-df08-4c27-91a5-3f7246a1bfdf', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('151e57f7-e7ab-458c-b789-4f8388449b86', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('a9bf0c60-27a7-4ab1-9b46-924d1d3d6840', 'e3e3c12a-332a-468c-a41d-c6302beb84d1', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789735204, 1789735204);
