INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('3ba0b654-511a-4666-9b10-e49be5220c18', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'A 68-year-old non-pregnant female with lower urinary tract infection symptoms (dysuria, frequency, no fever or flank pain) has a documented eGFR of 32 mL/min. (Case Ref: INFECTIONS-0504). Relevant physiological and medication history have been reviewed.', 'Which empirical oral antimicrobial is most appropriate under UKHSA guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b1e00216-2904-420e-a640-84570fbc7da7', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ca5a1b18-d837-4598-b36e-c446765afce1', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2d0a9854-5b38-4d6d-9a7c-8508455deb30', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1e3587bf-b38c-4d50-be16-09cbd5804e16', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0b790795-87b2-45bb-b88d-0656cc9a6763', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7e25b6f4-2fbf-483c-bfc2-001ee6f69882', '7f6890ff-f0eb-4b70-8b83-f920e3cc9841', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789735204, 1789735204);
