INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('52e98789-e66f-49dc-b88a-243e7466b61d', 'ACP-Q-0509', 1, 'published', 'p-mpharm', 'sub-cdiff', 'easy', 'sba', 'community', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('b6f76be1-98cb-4596-afa6-24b41bd4e004', '52e98789-e66f-49dc-b88a-243e7466b61d', 'A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0509). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fdfcf5af-2cfc-49c0-80aa-9815ba53234f', '52e98789-e66f-49dc-b88a-243e7466b61d', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('dc6ae7bb-9cba-497c-bb02-612e529336f2', '52e98789-e66f-49dc-b88a-243e7466b61d', 'B', 'Administer the next scheduled 24-hour dose on time with reduced milligram amount', 0, 'Sub-optimal. Reducing dose compromises peak concentration (Cmax:MIC bactericidal efficacy); interval extension is the correct kinetic strategy.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c91e35e3-6bd5-4576-afc7-c4e4d4f4eaf5', '52e98789-e66f-49dc-b88a-243e7466b61d', 'C', 'Double the dose to achieve faster bactericidal synergy', 0, 'Extremely dangerous. Causes catastrophic renal tubular necrosis and permanent vestibular/cochlear hair cell damage.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a03ad466-7460-425a-866d-f29b0772ef82', '52e98789-e66f-49dc-b88a-243e7466b61d', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f5977a71-61ae-4af5-aa93-510fdb026a9e', '52e98789-e66f-49dc-b88a-243e7466b61d', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('4243306c-2586-4c65-87d2-e7ee9d8370b2', '52e98789-e66f-49dc-b88a-243e7466b61d', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('9a6708e1-f2b9-41e8-8c52-e5086cd4cd94', '52e98789-e66f-49dc-b88a-243e7466b61d', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
