INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5294df61-25e6-4367-b7f1-27d8e9ad0608', '1a0ad7f6-c58d-456f-a808-95ee364e1694', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1dc019ce-553b-4996-ab72-aff24f202c03', '1a0ad7f6-c58d-456f-a808-95ee364e1694', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f491c475-db34-40ad-89b9-45401386ec8a', '1a0ad7f6-c58d-456f-a808-95ee364e1694', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('68365690-011c-4a95-9076-cf89893b5ca9', '1a0ad7f6-c58d-456f-a808-95ee364e1694', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
