INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('08424f8b-7140-4da1-a367-769d50a1beeb', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'A 68-year-old non-pregnant female with lower urinary tract infection symptoms (dysuria, frequency, no fever or flank pain) has a documented eGFR of 32 mL/min. (Case Ref: INFECTIONS-0532). Relevant physiological and medication history have been reviewed.', 'Which empirical oral antimicrobial is most appropriate under UKHSA guidance?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('33ff58d3-aebe-4ad2-971a-b4da1189acc5', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('834e3986-e0e5-4f9d-9132-2f28457a4617', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('45845576-5cf1-4174-b752-3ed54a055c8c', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a76450af-4404-451d-819d-5529980e2b2b', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('82724573-dc14-4d02-83db-185f358ac722', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7d93ec8e-f113-4450-8e04-3de4ea737676', 'd752c891-3109-4fe7-9c86-0df837fd8f97', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789735204, 1789735204);
