INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('80a65d5b-74cf-4dab-b329-7bbd82a91e2d', 'e78a8cb9-39d1-4d66-bb72-2f530ccb9d4b', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789735204);
