INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fe4c10fa-9cdc-4e67-8b0e-8c3d49d9a4ee', '9c440525-c740-40da-8f29-e8000a5ae68f', 'A', 'Pivmecillinam 400 mg initial dose then 200 mg three times daily for 3 days', 1, 'Correct. Nitrofurantoin is contraindicated when eGFR is below 45 mL/min (risk of therapeutic failure and peripheral neuropathy). Pivmecillinam or Trimethoprim (if low local resistance) are appropriate.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ec8199f4-e24e-4001-ba65-922ff0735efa', '9c440525-c740-40da-8f29-e8000a5ae68f', 'B', 'Nitrofurantoin 100 mg modified-release twice daily for 3 days', 0, 'Sub-optimal and contraindicated. Ineffective urinary concentration and toxic accumulation occur at eGFR < 45 mL/min.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a9dd0023-cdf0-47bc-a719-5614447950f6', '9c440525-c740-40da-8f29-e8000a5ae68f', 'C', 'Ciprofloxacin 500 mg twice daily for 7 days', 0, 'Contraindicated for uncomplicated lower UTI. MHRA warning restricts fluoroquinolones due to persistent, disabling musculoskeletal and neurological toxicities.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4cf5ab89-5ca7-41be-8c61-03436f582422', '9c440525-c740-40da-8f29-e8000a5ae68f', 'D', 'Amoxicillin 500 mg three times daily for 7 days', 0, 'Deprecated due to high nationwide E. coli resistance rates (> 50%).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6b5a345c-10fd-47cd-94d0-6dcde7831bec', '9c440525-c740-40da-8f29-e8000a5ae68f', 'E', 'Extend antibiotic duration to 14 days without urine culture review', 0, 'Excessive duration promotes antimicrobial resistance; standard female lower UTI duration is 3 days.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('35300e80-56b1-4f01-b943-4e7d12ac28e2', '9c440525-c740-40da-8f29-e8000a5ae68f', 'Nitrofurantoin requires eGFR >= 45 mL/min. Uncomplicated female lower UTI treatment duration is 3 days.', 'Trimethoprim can artificially elevate serum creatinine by inhibiting tubular secretion without altering true GFR. Reference: NICE NG109 & UKHSA Primary Care Antimicrobial Guidance.', 'NICE NG109 & UKHSA Primary Care Antimicrobial Guidance', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('68d64ff0-752e-4e7e-b427-7fb7c610969e', '9c440525-c740-40da-8f29-e8000a5ae68f', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('e3a29e05-4ab6-4761-9cde-997f4935535b', 'ACP-Q-0555', 1, 'published', 'p-mpharm', 'sub-allergy', 'easy', 'sba', 'community', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ff19642d-3c84-4c62-abad-512241bdfa86', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0555). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1857755f-111e-4e49-a7c5-461deaf0f152', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('49a01ce8-c9a5-4caa-a148-56a3f8d57a9b', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'B', 'Administer the next scheduled 24-hour dose on time with reduced milligram amount', 0, 'Sub-optimal. Reducing dose compromises peak concentration (Cmax:MIC bactericidal efficacy); interval extension is the correct kinetic strategy.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('52f8dbd8-8c0e-40f6-9173-4537d1111252', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'C', 'Double the dose to achieve faster bactericidal synergy', 0, 'Extremely dangerous. Causes catastrophic renal tubular necrosis and permanent vestibular/cochlear hair cell damage.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('399679fe-9b0d-4368-9fee-daf8b701429a', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0146c558-a7b0-48aa-ab35-9ce611472210', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('8158cce2-9ac7-4e14-9311-20a32e9073d2', 'e3a29e05-4ab6-4761-9cde-997f4935535b', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789735204, 1789735204);
