INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('65507d85-ad3f-4166-9bb7-9c74c3a6d8db', '2b57595c-4f18-4447-ab59-574ccd1653b7', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
