INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('9798a12e-a24b-4c28-bded-46909993c0fe', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0583). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('373076d6-cc0d-42b2-a80c-5ad0153c7ccb', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e8f8b496-870a-4709-8da6-d79f9102b100', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'B', 'Administer the next scheduled 24-hour dose on time with reduced milligram amount', 0, 'Sub-optimal. Reducing dose compromises peak concentration (Cmax:MIC bactericidal efficacy); interval extension is the correct kinetic strategy.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('58cdb261-707d-4d2b-963c-e89e17cb383c', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'C', 'Double the dose to achieve faster bactericidal synergy', 0, 'Extremely dangerous. Causes catastrophic renal tubular necrosis and permanent vestibular/cochlear hair cell damage.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('88cc6921-aac9-441a-a456-cf054322ad6f', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'D', 'Switch to multiple-daily dosing (80 mg TDS) without trough monitoring', 0, 'Deprecated. Once-daily dosing provides equal efficacy with lower renal accumulation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2eed71d0-386d-4eb4-9630-92e66cfb0c9f', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'E', 'Measure peak level at 30 minutes and disregard the 10-hour level', 0, 'Nomograms rely on single timed post-dose samples (6-14 hours); trough clearance is the primary safety determinant.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('5c98162a-dd2f-4b2d-b705-0a9da6ea9431', '7d80c061-725e-47ff-bff8-b5ffe809e2a3', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789735204, 1789735204);
