INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('fe61db77-757c-4e4b-ba35-653f7a5f48ae', 'bd34cb99-f09b-43e2-a77b-6052bd8457f6', 'Once-daily aminoglycoside dosing relies on interval adjustment (24h to 36h/48h) rather than dose reduction when clearance is delayed.', 'Gentamicin target trough concentration is < 1 mg/L to avoid inner ear and kidney toxicity. Reference: BNF Section 5.1.4 & UK Sepsis Trust Guidelines.', 'BNF Section 5.1.4 & UK Sepsis Trust Guidelines', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('7373a36d-4442-4fbc-81ec-86c79f0e123c', 'bd34cb99-f09b-43e2-a77b-6052bd8457f6', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
