INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('10a0c0f4-4c3e-4e48-b0e7-169f5abccb52', '6ded19ec-3d3b-4d73-b7f8-5187cfcd5ae3', 'A 64-year-old male receives once-daily IV Gentamicin (5 mg/kg) for severe Gram-negative sepsis. A serum concentration sampled 10 hours after the first infusion returns at 4.2 mg/L. (Case Ref: INFECTIONS-0595). Relevant physiological and medication history have been reviewed.', 'Using standard Hartford once-daily nomogram principles, what is the appropriate management decision?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('62bff064-21d2-4c28-82c1-0c981924d11b', '6ded19ec-3d3b-4d73-b7f8-5187cfcd5ae3', 'A', 'Extend dosing interval from 24 hours to 36 or 48 hours in accordance with nomogram plot', 1, 'Correct. A 10-hour level of 4.2 mg/L falls into the extended interval zone (36h or 48h). Extending interval allows trough levels to drop below 1 mg/L, preventing ototoxicity and nephrotoxicity.', 0, 1789735204);
